create extension if not exists pgcrypto;
do $$ begin create type app_role as enum ('admin'); exception when duplicate_object then null; end $$;
do $$ begin create type vehicle_status as enum ('available','assigned','maintenance','archived'); exception when duplicate_object then null; end $$;
do $$ begin create type session_status as enum ('active','completed'); exception when duplicate_object then null; end $$;
do $$ begin create type inspection_type as enum ('pre_trip','return'); exception when duplicate_object then null; end $$;
do $$ begin create type inspection_result as enum ('pass','issue'); exception when duplicate_object then null; end $$;
do $$ begin create type damage_status as enum ('open','in_review','repaired','closed'); exception when duplicate_object then null; end $$;
do $$ begin create type damage_type as enum ('scratch','dent','crack','paint','missing_part','other'); exception when duplicate_object then null; end $$;
do $$ begin create type blueprint_view as enum ('front','rear','left','right','roof','interior'); exception when duplicate_object then null; end $$;
do $$ begin create type damage_source as enum ('baseline','driver'); exception when duplicate_object then null; end $$;
create table if not exists public.user_roles (id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id) on delete cascade not null, role app_role not null, unique (user_id, role));
create or replace function public.has_role(_user_id uuid, _role app_role) returns boolean language sql stable security definer set search_path = public as $$ select exists (select 1 from public.user_roles where user_id = _user_id and role = _role); $$;
create table if not exists public.drivers (id uuid primary key default gen_random_uuid(), name text not null, surname text not null, employee_number text not null unique, pin_hash text not null, active boolean not null default true, created_at timestamptz not null default now(), mobile text, licence_number text, licence_type text check (licence_type in ('local', 'international')), licence_category text, cpc_valid boolean not null default false, cpc_expiry_date date);
create table if not exists public.vehicles (id uuid primary key default gen_random_uuid(), registration_number text not null unique, make text not null, model text not null, year int, vin text, status vehicle_status not null default 'available', archived boolean not null default false, created_at timestamptz not null default now(), road_licence_date date, road_licence_due date, last_service_date date, service_due_date date);
create table if not exists public.vehicle_sessions (id uuid primary key default gen_random_uuid(), driver_id uuid not null references public.drivers(id) on delete restrict, vehicle_id uuid not null references public.vehicles(id) on delete restrict, started_at timestamptz not null default now(), ended_at timestamptz, status session_status not null default 'active', odometer_start numeric, odometer_end numeric);
create index if not exists idx_sessions_driver on public.vehicle_sessions(driver_id);
create index if not exists idx_sessions_vehicle on public.vehicle_sessions(vehicle_id);
create table if not exists public.inspections (id uuid primary key default gen_random_uuid(), session_id uuid not null references public.vehicle_sessions(id) on delete cascade, driver_id uuid not null references public.drivers(id), vehicle_id uuid not null references public.vehicles(id), inspection_type inspection_type not null, created_at timestamptz not null default now(), items_pass_count integer not null default 0, items_issue_count integer not null default 0);
create table if not exists public.inspection_items (id uuid primary key default gen_random_uuid(), inspection_id uuid not null references public.inspections(id) on delete cascade, item_name text not null, result inspection_result not null, notes text);
create index if not exists idx_inspection_items_inspection on public.inspection_items(inspection_id);
create table if not exists public.inspection_item_photos (id uuid primary key default gen_random_uuid(), inspection_item_id uuid not null references public.inspection_items(id) on delete cascade, photo_url text not null);
create index if not exists idx_inspection_item_photos_item on public.inspection_item_photos(inspection_item_id);
create table if not exists public.damage_markers (id uuid primary key default gen_random_uuid(), vehicle_id uuid not null references public.vehicles(id) on delete cascade, driver_id uuid references public.drivers(id), damage_type damage_type not null, description text, status damage_status not null default 'open', x_coordinate numeric not null, y_coordinate numeric not null, view blueprint_view not null, reported_at timestamptz not null default now(), source damage_source not null default 'driver', approved boolean not null default false, approved_at timestamptz, approved_by uuid references auth.users(id), rejection_reason text, session_id uuid references public.vehicle_sessions(id) on delete set null, reported_during text check (reported_during in ('pre_trip', 'return')));
create index if not exists idx_damage_markers_vehicle on public.damage_markers(vehicle_id);
create index if not exists idx_damage_markers_driver on public.damage_markers(driver_id);
create index if not exists idx_damage_markers_session on public.damage_markers(session_id);
create index if not exists idx_damages_pending_approval on public.damage_markers(source, approved, status) where source = 'driver' and approved = false;
create index if not exists idx_damages_admin_list on public.damage_markers(reported_at desc);
create table if not exists public.damage_marker_photos (id uuid primary key default gen_random_uuid(), damage_marker_id uuid not null references public.damage_markers(id) on delete cascade, photo_url text not null, approved boolean not null default false, approved_at timestamptz, approved_by uuid references auth.users(id), uploaded_at timestamptz not null default now());
create index if not exists idx_damage_photos_marker on public.damage_marker_photos(damage_marker_id);
create table if not exists public.vehicle_blueprints (id uuid primary key default gen_random_uuid(), vehicle_id uuid not null references public.vehicles(id) on delete cascade, blueprint_image text not null, view blueprint_view, updated_at timestamptz not null default now(), constraint vehicle_blueprints_vehicle_view_unique unique (vehicle_id, view));
create table if not exists public.vehicle_base_photos (id uuid primary key default gen_random_uuid(), vehicle_id uuid not null references public.vehicles(id) on delete cascade, photo_url text not null, view blueprint_view, label text, created_at timestamptz not null default now());
create index if not exists idx_base_photos_vehicle on public.vehicle_base_photos(vehicle_id);
create table if not exists public.damage_marker_base_photos (id uuid primary key default gen_random_uuid(), damage_marker_id uuid not null references public.damage_markers(id) on delete cascade, base_photo_id uuid not null references public.vehicle_base_photos(id) on delete cascade, unique (damage_marker_id, base_photo_id));
create index if not exists idx_dmbp_marker on public.damage_marker_base_photos(damage_marker_id);
create table if not exists public.checklist_items (id uuid primary key default gen_random_uuid(), item_text text not null, item_order int not null default 0, is_active boolean not null default true, created_at timestamptz not null default now(), checklist_type text not null default 'pre_trip' check (checklist_type in ('pre_trip', 'return')), item_key text unique);
create index if not exists idx_checklist_items_order on public.checklist_items(item_order);
create table if not exists public.vehicle_checklist_items (id uuid primary key default gen_random_uuid(), vehicle_id uuid not null references public.vehicles(id) on delete cascade, checklist_item_id uuid not null references public.checklist_items(id) on delete cascade, enabled boolean not null default true, unique (vehicle_id, checklist_item_id));
create index if not exists idx_vehicle_checklist_vehicle on public.vehicle_checklist_items(vehicle_id);
create table if not exists public.vehicle_logbooks (id uuid primary key default gen_random_uuid(), vehicle_id uuid not null references public.vehicles(id) on delete cascade, file_path text not null, file_name text not null, uploaded_at timestamptz not null default now());
create table if not exists public.vehicle_repairs (id uuid primary key default gen_random_uuid(), vehicle_id uuid not null references public.vehicles(id) on delete cascade, repair_date date not null, description text not null, cost numeric(10, 2), resolved boolean not null default false, created_at timestamptz not null default now());